    id,
    name,
    columns,
    rowHeight,
    cells: cells as DashboardLayout["cells"],
    layouts: Object.keys(layouts).length > 0 ? layouts : undefined
  };
}

function normalizeDashboardCell(input: any, index: number, columns: number): DashboardLayout["cells"][number] | undefined {
  if (!input || typeof input !== "object") return undefined;
  const viewType = String(input.viewType ?? "streams");
  if (!["streams", "detail", "timeline", "topology", "events"].includes(viewType)) return undefined;
  const grid = input.grid ?? {};
  const w = clampInt(grid.w, 2, columns, 6);
  const x = clampInt(grid.x, 0, Math.max(0, columns - w), 0);
  return {
    id: String(input.id ?? `cell-${index + 1}`),
    title: String(input.title ?? viewType),
    viewType: viewType as DashboardLayout["cells"][number]["viewType"],
    grid: {
      x,
      y: clampInt(grid.y, 0, 200, index * 8),
      w,
      h: clampInt(grid.h, 3, 40, 8)
    },
    params: input.params && typeof input.params === "object" ? input.params : undefined
  };
}

