  if (value === undefined || value === null || value === "") return defaultValue;
  const normalized = String(value).trim().toLowerCase();
  if (["1", "true", "yes", "on"].includes(normalized)) return true;
  if (["0", "false", "no", "off"].includes(normalized)) return false;
  return defaultValue;
}
import { readFile, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import type { FastifyInstance } from "fastify";
import type { StreamStore } from "../state/store";
import { config } from "../config";
import { queryInterfaceMetricsHistory, queryMetricsSnapshotAt, queryStreamMetricsHistory } from "../history/query";
import { queryTimelineHistory } from "../history/timeline_query";
import { queryEventsHistory } from "../history/events_query";
import { queryProjectedTopologyAt } from "../history/topology_state_query";
import { enrichProjectedStreamSnapshot, queryProjectedStreamsAt } from "../history/stream_state_query";
import type { DashboardLayout, TimelineRow, TimelineViewResponse } from "../types";

export async function registerRoutes(app: FastifyInstance, store: StreamStore) {
  app.addHook("onSend", async (_request, reply, payload) => {
    reply.header("Cache-Control", "no-store");
    return payload;
  });

  app.get("/api/config", async () => ({
    lostRetentionSec: config.lostRetentionSec,
    historyWindowSec: config.historyWindowSec,
    staleAfterSec: config.staleAfterSec
  }));

  app.get("/api/summary", async () => store.getSummary());

  app.get("/api/dashboard-layouts", async () => readDashboardLayouts());

  app.put<{ Body: DashboardLayout[] }>("/api/dashboard-layouts", async (request) => {
    const layouts = Array.isArray(request.body) ? request.body : [DEFAULT_DASHBOARD_LAYOUT];
    await writeDashboardLayouts(layouts);
    return readDashboardLayouts();
  });


  app.get("/api/bootstrap", async () => ({
    streams: store.listStreams(),
    interfaces: store.listInterfaces(),
    timeline: store.listTimeline(),
    summary: store.getSummary(),
    events: store.listEvents({ limit: 100 })
  }));

  app.get("/api/interfaces", async () => store.listInterfaces());

  app.get<{ Params: { interfaceId: string }; Querystring: { windowSec?: string; from?: string; to?: string } }>(
    "/api/interfaces/:interfaceId/metrics",
    async (request, reply) => {
      const interfaceId = Number(request.params.interfaceId);
      const windowSec = request.query.windowSec ? Number(request.query.windowSec) : undefined;
      if (!Number.isInteger(interfaceId)) return reply.code(400).send({ error: "invalid interface id" });
      const metrics = store.getInterfaceMetrics(interfaceId, Number.isFinite(windowSec) ? windowSec : undefined);
      if (!metrics) return reply.code(404).send({ error: "interface not found" });
      return metrics;
    }
  );

  app.get<{ Params: { key: string }; Querystring: { windowSec?: string; from?: string; to?: string } }>(
    "/api/interfaces/by-key/:key/metrics",
    async (request, reply) => {
      const key = decodeURIComponent(request.params.key);
      const windowSec = request.query.windowSec ? Number(request.query.windowSec) : undefined;
      const from = request.query.from ? Number(request.query.from) : undefined;
      const to = request.query.to ? Number(request.query.to) : undefined;
      if (Number.isFinite(from) && Number.isFinite(to) && to! > from!) {
        const metrics = await queryInterfaceMetricsHistory({ key, from: from!, to: to! });
        if (!metrics) return reply.code(404).send({ error: "interface history not available" });
        return metrics;
      }
      const metrics = store.getInterfaceMetricsByKey(key, Number.isFinite(windowSec) ? windowSec : undefined);
      if (!metrics) return reply.code(404).send({ error: "interface not found" });
      return metrics;
    }
  );

  app.get<{ Querystring: { time?: string } }>("/api/streams", async (request, reply) => {
    const time = request.query.time ? Number(request.query.time) : undefined;
    if (Number.isFinite(time)) {
      let snapshot = await queryProjectedStreamsAt(config.streamStateDir, time!);
      if (!snapshot) return reply.code(404).send({ error: "streams snapshot not available" });
      const metricsSnapshot = await queryMetricsSnapshotAt(time!);
      if (metricsSnapshot) snapshot = enrichProjectedStreamSnapshot(snapshot, metricsSnapshot.interfaces, metricsSnapshot.metrics);
      return snapshot;
    }
    return store.listStreams();
  });

  app.get<{ Querystring: { time?: string } }>("/api/topology", async (request, reply) => {
    const time = request.query.time ? Number(request.query.time) : undefined;
    if (Number.isFinite(time)) {
      const snapshot = await queryProjectedTopologyAt({
        checkpointDir: config.topologyCheckpointDir,
        updatesDir: config.topologyUpdatesDir,
        time: time!
      });
      if (!snapshot) return reply.code(404).send({ error: "topology snapshot not available" });
      return snapshot;
    }
    const topology = store.getTopology();
    if (config.diagnosticLog) console.error("[STM_DIAG] api topology status=" + (topology ? "200" : "404") + " nodes=" + (topology?.nodes.length ?? 0) + " edges=" + (topology?.edges.length ?? 0));
    if (!topology) return reply.code(404).send({ error: "topology snapshot not available" });
    return topology;
  });

  app.get<{ Querystring: { from?: string; to?: string; includeFlows?: string } }>("/api/timeline", async (request): Promise<TimelineViewResponse> => {
    const from = request.query.from ? Number(request.query.from) : undefined;
    const to = request.query.to ? Number(request.query.to) : undefined;
    if (Number.isFinite(from) && Number.isFinite(to) && to! > from!) {
      return queryTimelineHistory({
        from: from!,
        to: to!,
        includeFlows: request.query.includeFlows !== "0"
      });
    }
    const rows = store.listTimeline();
    const bounds = timelineBounds(rows);
    return {
      rows,
      window: bounds,
      available: bounds,
      source: "live"
    };
  });

  app.get<{ Querystring: { streamKey?: string; flowKey?: string; interfaceId?: string; limit?: string; from?: string; to?: string; proto?: string; level?: string; type?: string } }>("/api/events", async (request) => {
    const limit = request.query.limit ? Number(request.query.limit) : undefined;
    const interfaceId = request.query.interfaceId ? Number(request.query.interfaceId) : undefined;
    const from = request.query.from ? Number(request.query.from) : undefined;
    const to = request.query.to ? Number(request.query.to) : undefined;
    const level = request.query.level;
    if (Number.isFinite(from) && Number.isFinite(to) && to! > from!) {
      const result = await queryEventsHistory({
        from: from!,
        to: to!,
        streamKey: request.query.streamKey,
        flowKey: request.query.flowKey,
        interfaceId: Number.isInteger(interfaceId) ? interfaceId : undefined,
        proto: request.query.proto,
        level: level === "info" || level === "warn" || level === "error" ? level : undefined,
        type: request.query.type,
        limit: Number.isFinite(limit) ? limit : undefined
      });
      if (config.diagnosticLog) console.error("[STM_DIAG] api events range=" + from + "-" + to + " result=" + result.length + " journal=" + config.eventJournalDir);
      return result;
    }
    const result = store.listEvents({
      streamKey: request.query.streamKey,
      flowKey: request.query.flowKey,
      interfaceId: Number.isInteger(interfaceId) ? interfaceId : undefined,
      limit: Number.isFinite(limit) ? limit : undefined
    });
    if (config.diagnosticLog) console.error("[STM_DIAG] api events live result=" + result.length + " journal=" + config.eventJournalDir);
    return result;
  });

  app.get<{ Params: { streamKey: string } }>("/api/streams/:streamKey", async (request, reply) => {
    const stream = store.getStream(decodeURIComponent(request.params.streamKey));
    if (!stream) return reply.code(404).send({ error: "stream not found" });
    return stream;
  });

  app.get<{ Params: { streamKey: string }; Querystring: { windowSec?: string; from?: string; to?: string; resolutionSec?: string } }>(
    "/api/streams/:streamKey/metrics",
    async (request, reply) => {
      const streamKey = decodeURIComponent(request.params.streamKey);
      const from = request.query.from ? Number(request.query.from) : undefined;
      const to = request.query.to ? Number(request.query.to) : undefined;
      const resolutionSec = request.query.resolutionSec ? Number(request.query.resolutionSec) : undefined;
      if (Number.isFinite(from) && Number.isFinite(to) && to! > from!) {
        return queryStreamMetricsHistory({
          streamKey,
          from: from!,
          to: to!,
          resolutionSec: Number.isFinite(resolutionSec) ? resolutionSec : undefined
        });
      }
      const windowSec = request.query.windowSec ? Number(request.query.windowSec) : undefined;
      const metrics = store.getMetrics(streamKey, Number.isFinite(windowSec) ? windowSec : undefined);
      if (!metrics) return reply.code(404).send({ error: "stream not found" });
      return metrics;
    }
  );
}

function timelineBounds(rows: TimelineRow[]) {
  if (rows.length === 0) {
    const now = Date.now() / 1000;
    return { from: now - 300, to: now };
  }

  let from = Number.POSITIVE_INFINITY;
  let to = Number.NEGATIVE_INFINITY;
  for (const row of rows) {
    from = Math.min(from, row.firstSeen, ...row.segments.map((segment) => segment.start));
    to = Math.max(to, row.lastSeen, ...row.segments.map((segment) => segment.end ?? row.lastSeen));
  }

  if (!Number.isFinite(from) || !Number.isFinite(to) || to <= from) {
    const now = Date.now() / 1000;
    return { from: now - 300, to: now };
  }

  return { from, to };
}


const DEFAULT_DASHBOARD_LAYOUT: DashboardLayout = {
  id: "default",
  name: "Default dashboard",
  columns: 24,
  rowHeight: 32,
  cells: [
    { id: "streams", title: "Streams", viewType: "streams", grid: { x: 0, y: 0, w: 8, h: 11 } },
    { id: "detail", title: "Detail", viewType: "detail", grid: { x: 8, y: 0, w: 8, h: 11 } },
    { id: "topology", title: "Topology", viewType: "topology", grid: { x: 16, y: 0, w: 8, h: 11 } },
    { id: "timeline", title: "Timeline", viewType: "timeline", grid: { x: 0, y: 11, w: 14, h: 8 } },
    { id: "events", title: "Events", viewType: "events", grid: { x: 14, y: 11, w: 10, h: 8 } }
  ]
};

async function readDashboardLayouts(): Promise<DashboardLayout[]> {
  if (!existsSync(config.dashboardLayoutsFile)) return [DEFAULT_DASHBOARD_LAYOUT];
  try {
    const parsed = JSON.parse(await readFile(config.dashboardLayoutsFile, "utf8")) as unknown;
    if (!Array.isArray(parsed)) return [DEFAULT_DASHBOARD_LAYOUT];
    const layouts = parsed.map(normalizeDashboardLayout).filter(Boolean) as DashboardLayout[];
    return layouts.length > 0 ? layouts : [DEFAULT_DASHBOARD_LAYOUT];
  } catch {
    return [DEFAULT_DASHBOARD_LAYOUT];
  }
}

async function writeDashboardLayouts(layouts: DashboardLayout[]) {
  await writeFile(config.dashboardLayoutsFile, `${JSON.stringify(layouts.map(normalizeDashboardLayout).filter(Boolean), null, 2)}\n`, "utf8");
}

function normalizeDashboardLayout(input: any): DashboardLayout | undefined {
  if (!input || typeof input !== "object") return undefined;
  const id = String(input.id ?? "default");
  const name = String(input.name ?? id);
  const columns = clampInt(input.columns, 6, 48, 24);
  const rowHeight = clampInt(input.rowHeight, 20, 80, 32);
  const legacyCells = Array.isArray(input.cells) ? input.cells.map((cell: any, index: number) => normalizeDashboardCell(cell, index, columns)).filter(Boolean) : [];
  const responsiveColumns = { desktop: 24, tablet: 12, mobile: 4 } as const;
  const layouts: NonNullable<DashboardLayout["layouts"]> = {};
  if (input.layouts && typeof input.layouts === "object") {
    for (const breakpoint of ["desktop", "tablet", "mobile"] as const) {
      const rawCells = input.layouts[breakpoint];
      if (!Array.isArray(rawCells)) continue;
      const normalized = rawCells.map((cell: any, index: number) => normalizeDashboardCell(cell, index, responsiveColumns[breakpoint])).filter(Boolean);
      if (normalized.length > 0) layouts[breakpoint] = normalized as DashboardLayout["cells"];
    }
  }
  const cells = layouts.desktop ?? legacyCells;
  return {
    id,
    name,
    columns,
    rowHeight,
    cells: cells as DashboardLayout["cells"],
    layouts: Object.keys(layouts).length > 0 ? layouts : undefined
  };
}

function normalizeDashboardCell(input: any, index: number, columns: number): DashboardLayout["cells"][number] | undefined {
  if (!input || typeof input !== "object") return undefined;
  const viewType = String(input.viewType ?? "streams");
  if (!["streams", "detail", "timeline", "topology", "events"].includes(viewType)) return undefined;
  const grid = input.grid ?? {};
  const w = clampInt(grid.w, 2, columns, 6);
  const x = clampInt(grid.x, 0, Math.max(0, columns - w), 0);
  return {
    id: String(input.id ?? `cell-${index + 1}`),
    title: String(input.title ?? viewType),
    viewType: viewType as DashboardLayout["cells"][number]["viewType"],
    grid: {
      x,
      y: clampInt(grid.y, 0, 200, index * 8),
      w,
      h: clampInt(grid.h, 3, 40, 8)
    },
    params: input.params && typeof input.params === "object" ? input.params : undefined
  };
}

function clampInt(value: unknown, min: number, max: number, fallback: number) {
  const numberValue = Number(value);
  if (!Number.isFinite(numberValue)) return fallback;
  return Math.max(min, Math.min(max, Math.round(numberValue)));
}
import { existsSync, statSync } from "node:fs";
import fastify, { type FastifyInstance } from "fastify";
import fastifyStatic from "@fastify/static";
import { config, ensureLogFilesExist } from "./config";
import { RotatingNdjsonTail } from "./ingest/rotatingNdjsonTail";
import { TailFile } from "./ingest/tailFile";
import { normalizeInterfacesLine, normalizeMetricsLine, normalizeStreamsLine, normalizeTimelineLine, normalizeTopologyLine } from "./normalizer";
import { applyProjectedLifecycleEvent, loadProjectedStreamState, materializeProjectedStreamStates, type JsonRecord } from "./history/stream_state_query";
import { queryProjectedTopologyAt } from "./history/topology_state_query";
import { queryEventsHistory } from "./history/events_query";
import { normalizeEventLine } from "./events";
import { registerRoutes } from "./api/routes";
import { StreamStore } from "./state/store";
import { SocketServer } from "./ws/socketServer";

type RunningTail = { start(): void; stop(): void };

async function main() {
  ensureLogFilesExist();
  diagnostic(`startup source=projected cwd=${process.cwd()} root=${config.rootDir} logDir=${config.logDir} port=${config.port}`);
  diagnosticInputs();

  const app = fastify({ logger: config.httpAccessLog });
  const store = new StreamStore(config.historyWindowSec, config.timelineWindowSec, config.staleAfterSec, config.lostRetentionSec, config.maxEvents, config.maxTimelineRows);
  const now = Date.now() / 1000;
  const initialEvents = await queryEventsHistory({ from: now - 24 * 3600, to: now, limit: config.maxEvents });
  for (const event of initialEvents.reverse()) store.addEvent(event);

  const initialTopology = await queryProjectedTopologyAt({ checkpointDir: config.topologyCheckpointDir, updatesDir: config.topologyUpdatesDir, time: now });
  if (initialTopology) store.applyTopologySnapshot(initialTopology);
  diagnostic(`initial state events=${store.listEvents({ limit: config.maxEvents }).length} topology=${initialTopology ? "loaded" : "missing"}`);

  await registerRoutes(app, store);
  if (existsSync(config.clientDist)) {
    await app.register(fastifyStatic, { root: config.clientDist, prefix: "/" });
    app.setNotFoundHandler((request, reply) => {
      if (request.raw.url?.startsWith("/api") || request.raw.url === "/ws") return reply.code(404).send({ error: "not found" });
      return reply.sendFile("index.html");
    });
  }

  const sockets = new SocketServer(app.server, store, config.streamsPatchIntervalMs, config.wsMaxBufferedBytes);
  sockets.start();
  const tails = await createProjectedTails(app, store);
  tails.forEach((tail) => tail.start());
  const close = async () => { tails.forEach((tail) => tail.stop()); await app.close(); };
  process.on("SIGINT", () => void close());
  process.on("SIGTERM", () => void close());
  await app.listen({ host: config.host, port: config.port });
}

async function createProjectedTails(app: FastifyInstance, store: StreamStore): Promise<RunningTail[]> {
  const state = await loadProjectedStreamState(config.streamStateDir, Number.POSITIVE_INFINITY);
  const applyStreams = (time: number) => store.applyStreamSnapshot(materializeProjectedStreamStates(state.streams, time), time);
  if (state.hasRecords) applyStreams(Date.now() / 1000);

  const streams = new RotatingNdjsonTail({ root: `${config.streamStateDir}/delta`, extension: ".ndjson", pollMs: config.pollMs, startAtLatestFile: true,
    recordId: sourceRecordId,
    initialSkipRecordIds: state.latestDeltaRecordIds,
    onLine: (line) => { try { const delta = parseRecord(line); const time = Number(delta?.time ?? 0); if (!delta || !Number.isFinite(time) || time < state.checkpointTime) return; applyProjectedLifecycleEvent(state.streams, delta.event); applyStreams(time); } catch (error) { app.log.warn({ error }, "failed to parse projected stream delta"); } },
    onError: (error) => app.log.warn({ error }, "failed to tail projected stream deltas") });
  const metrics = new RotatingNdjsonTail({ root: config.metricsRawDir, extension: ".jsonl", pollMs: config.pollMs, startAtLatestFile: true,
    onLine: (line) => ingestMetrics(store, line, app), onError: (error) => app.log.warn({ error }, "failed to tail projected metrics") });
  const events = new RotatingNdjsonTail({ root: config.eventJournalDir, extension: ".ndjson", pollMs: config.pollMs, startAtLatestFile: true,
    onLine: (line) => ingestEvent(store, line, app), onError: (error) => app.log.warn({ error }, "failed to tail event journal") });
  const timeline = new TailFile({ path: config.timelineLiveFile, pollMs: config.pollMs,
    onLine: (line) => ingestTimeline(store, line, app), onError: (error) => app.log.warn({ error }, "failed to tail projected timeline live") });
  const topology = new TailFile({ path: config.topologyLiveFile, pollMs: config.pollMs,
    onLine: (line) => ingestTopology(store, line, app), onError: (error) => app.log.warn({ error }, "failed to tail projected topology live") });
  return [streams, metrics, events, timeline, topology];
}

function ingestMetrics(store: StreamStore, line: string, app: FastifyInstance) {
  try { store.upsertInterfaces(normalizeInterfacesLine(line)); for (const item of normalizeMetricsLine(line)) store.addMetric(item); }
  catch (error) { app.log.warn({ error }, "failed to parse metrics line"); }
}
function ingestEvent(store: StreamStore, line: string, app: FastifyInstance) {
  try { const event = normalizeEventLine(line); if (event) store.addEvent(event); }
  catch (error) { app.log.warn({ error }, "failed to parse event line"); }
}
function ingestTimeline(store: StreamStore, line: string, app: FastifyInstance) {
  try { const item = normalizeTimelineLine(line); if (item) store.addTimelineEvent(item); }
  catch (error) { app.log.warn({ error }, "failed to parse timeline line"); }
}
function ingestTopology(store: StreamStore, line: string, app: FastifyInstance) {
  try { const snapshot = normalizeTopologyLine(line); if (snapshot) store.applyTopologySnapshot(snapshot); }
  catch (error) { app.log.warn({ error }, "failed to parse topology line"); }
}
function parseRecord(line: string): JsonRecord | undefined {
  try { const value = JSON.parse(line) as unknown; return value && typeof value === "object" && !Array.isArray(value) ? value as JsonRecord : undefined; } catch { return undefined; }
}
function sourceRecordId(line: string) { const delta = parseRecord(line); return typeof delta?.source_record_id === "string" ? delta.source_record_id : undefined; }
function diagnosticInputs() {
  const inputs = { streams: config.streamStateDir, metrics: config.metricsRawDir, events: config.eventJournalDir, timeline: config.timelineLiveFile, topology: config.topologyLiveFile };
  for (const [label, file] of Object.entries(inputs)) {
    try { const info = statSync(file); diagnostic(`input ${label} path=${file} size=${info.size} mtime=${info.mtime.toISOString()}`); }
    catch (error) { diagnostic(`input ${label} path=${file} error=${String(error)}`); }
  }
}
function diagnostic(message: string) { if (config.diagnosticLog) console.error("[STM_DIAG] " + message); }


main().catch((error) => { console.error(error); process.exit(1); });
