                        <button type="button" className={timelineExpandLevel === "proto" ? "active" : ""} onClick={() => setTimelineExpandLevel("proto")}>Proto</button>
                        <button type="button" className={timelineExpandLevel === "stream" ? "active" : ""} onClick={() => setTimelineExpandLevel("stream")}>Stream</button>
                        <button type="button" className={timelineExpandLevel === "flow" ? "active" : ""} onClick={() => setTimelineExpandLevel("flow")}>Flow</button>
                      </div>
                      <label className="detail-range-select timeline-range-select">
                        <span>Range</span>
                        <select value={timelineRange} onChange={(event) => {
                          setTimelineRange(event.target.value);
                          if (timelineFollowNow) setManualTimelineWindowEndSec(null);
                        }}>
                          {RANGE_OPTIONS.map((range) => <option key={range} value={range}>{range}</option>)}
                        </select>
                      </label>
                      <div className="timeline-browse-controls">
                        <button type="button" className={timelineFollowNow ? "active" : ""} onClick={() => { setTimelineFollowNow(true); setManualTimelineWindowEndSec(null); }}>Now</button>
                        <button type="button" className={!timelineFollowNow ? "active" : ""} onClick={() => { setTimelineFollowNow(false); setManualTimelineWindowEndSec(timelineWindow.to); }}>Browse</button>
                      </div>
                    </div>}
                  />}
                >
                  <div ref={timelineBodyRef} className="timeline-body pane-timeline-body" title="Ctrl + Wheel: move timeline window">
                    {timelineLoading && (
                      <div className="timeline-loading-overlay" role="status" aria-live="polite" aria-label="Loading timeline">
                        <div className="timeline-loading-dialog">
                          <div className="timeline-loading-spinner" />
                          <span>Loading timeline...</span>
                        </div>
                      </div>
                    )}
                    <TimelinePane
                      rows={filteredTimeline}
                      nowSec={summary.updatedAt ?? Date.now() / 1000}
                      fadeSec={appConfig.lostRetentionSec}
                      rangeStartSec={timelineWindow.from}
                      rangeEndSec={timelineWindow.to}
                      expandLevel={timelineExpandLevel}
                      interfaceNames={timelineInterfaceNames}
                    />
                    <div className="timeline-scrollbar">
                      <input
                        type="range"
                        min={0}
                        max={Math.max(1, timelineScrollbarMax)}
                        step={Math.max(1, Math.round(timelineWindowSec / 120))}
                        value={timelineScrollbarMax === 0 ? 0 : timelineScrollbarValue}
                        disabled={!enableTimelineBrowse}
                        onChange={(event) => {
                          const offset = Number(event.target.value);
                          setTimelineFollowNow(false);
                          setManualTimelineWindowEndSec(timelineAvailable.from + offset + timelineWindowSec);
                        }}
                      />
                    </div>
                  </div>
                </PaneFrame>
              )}
              {activeTab === "topology" && (
                <section className="standalone-view topology-tab-view">
                  <TopologyPane
                    selectedTimeSec={selectedTimeSec}
                    onSelectStream={(streamKey) => {
                      setSelectedInterfaceKey(null);
                      setSelectedStreamKey(streamKey);
                      setSelectedFlowKey(null);
                    }}
                    onSelectFlow={(streamKey, flowKey) => {
                      setSelectedInterfaceKey(null);
                      setSelectedStreamKey(streamKey);
                      setSelectedFlowKey(flowKey);
                    }}
                    onSelectTime={selectGlobalTime}
                  />
                </section>
              )}
              {activeTab === "events" && (
                <section className="standalone-view standalone-events">
                  <EventLog
                    events={events}
                    eventsRange={eventsRange}
                    onChangeEventsRange={setEventsRange}
                    selectedStreamKey={selectedStreamKey}
                    selectedFlowKey={selectedFlowKey}
                    selectedInterfaceId={selectedInterface?.interfaceId ?? null}
                  />
                </section>
              )}
            </section>
          )}
        </div>
      </div>
      {/* Strong guard against browser history swipe gestures during splitter drags; remove if it interferes with normal dragging. */}
      {resizingPane && <div className={`resize-capture resize-capture-${resizingPane}`} aria-hidden="true" />}
    </main>
  );
}

function titleForDashboardView(viewType: DashboardViewType) {
  switch (viewType) {
    case "streams": return "Streams";
    case "detail": return "Detail";
    case "timeline": return "Timeline";
    case "topology": return "Topology";
    case "events": return "Events";
  }
}

function nextDashboardY(cells: DashboardCell[]) {
  return cells.reduce((max, cell) => Math.max(max, cell.grid.y + cell.grid.h), 0);
}

