    def __command_reconfig(self, args):
        file = args[0] if args[0] != 'default' else self.configfile
        config = self.__load_config(file)
        if(len(config) == 0):
            logging.critical('reconfig: invalid config file \'%s\'.', file)
            return 'error: invalid configuration.'

        self.environ = self.__build_environ(self.config)
        eprint(self.environ)
        apply_environ(self.environ, config)

        if config == self.config:
            logging.critical('reconfig: configuration has not changed.')
            return 'ok'

        changed = {}
        for k, v in config.items():
            if k in self.config:
                if v != self.config[k]:
                    command_argv = to_argv(v['command'])
                    if len(command_argv) == 0 or not os.path.isfile(command_argv[0]):
                        return 'error: ' + k + ': invalid command' + '\'' + str(v['command']) + '\'.'
                    if v.get('stdin') != self.config[k].get('stdin'):
                        return 'error: ' + k + ': i/o mismatch.'
                    if v.get('stdout') != self.config[k].get('stdout'):
                        return 'error: ' + k + ': i/o mismatch.'
