    def __command_stop(self, args):
        if(args[0] == 'all'):
            self.ongoing = False
        else:
            for t in args:
                if t in self.procs:
                    self.procs[t].stop();
                    logging.info('stop \'%s\'', t)
                else:
                    logging.error('error: failed to stop \'%s\'', t)
                    return 'error: failed to stop \'' + t + '\'';
        return 'ok'

    def __command_ps(self, args):
        stat = {}
        for k, v in self.procs.items():
             stat[k] = {"pid": v.prc.pid, "command": v.command, "options": v.options}
        return json.dumps(stat)

    def __command_reconfig(self, args):
        file = args[0] if args[0] != 'default' else self.configfile
        config = self.__load_config(file)
        if(len(config) == 0):
            logging.critical('reconfig: invalid config file \'%s\'.', file)
            return 'error: invalid configuration.'

        self.environ = self.__build_environ(self.config)
        eprint(self.environ)
        apply_environ(self.environ, config)

        if config == self.config:
            logging.critical('reconfig: configuration has not changed.')
            return 'ok'

        changed = {}
        for k, v in config.items():
            if k in self.config:
                if v != self.config[k]:
                    command_argv = to_argv(v['command'])
                    if len(command_argv) == 0 or not os.path.isfile(command_argv[0]):
                        return 'error: ' + k + ': invalid command' + '\'' + str(v['command']) + '\'.'
                    if v.get('stdin') != self.config[k].get('stdin'):
                        return 'error: ' + k + ': i/o mismatch.'
                    if v.get('stdout') != self.config[k].get('stdout'):
                        return 'error: ' + k + ': i/o mismatch.'
                    changed[k] = v

        if len(changed) > 0:
            logging.info('reconfig: %s', changed.keys())

            for k, v in changed.items():
                self.procs[k].command = v['command']
                self.procs[k].options = v.get('options', [])
                self.procs[k].pre     = v.get('pre', '')

            for k, v in changed.items():
                logging.critical('reconfig: %s', k)
                self.procs[k].stop()

        self.config = config

        return 'ok'

