#include "util.h"

static const char VERSION_STR[] = "0.0";



//--------------------------------------------------------------------------------
app::app() {
	m_abort = false;
}

//--------------------------------------------------------------------------------
app::~app() {
}

//--------------------------------------------------------------------------------
int app::run(int argc, char *argv[]) {
	if(parse_options(argc, argv, &m_param) != 0) {
		return -1;
	}

    task reporter(std::bind(&app::report, this), 1000);
    reporter.start();

    m_monitor = std::make_unique<monitor>(monitor::config{
		    .log = {
			    .dir = m_param.log_dir,
			    .event_journal_dir = m_param.event_journal_dir,
			    .metrics_journal_dir = m_param.metrics_journal_dir,
			    .journal_part_size_bytes = m_param.journal_part_size_bytes,
			    .journal_retention_hours = m_param.journal_retention_hours,
		    },
		    .input = {
			    .input_mode = m_param.input_mode,
			    .watch_dir = m_param.input_watch_dir,
			    .file = m_param.input_file,
			    .dir = m_param.input_dir,
			    .pcap_prefix = m_param.pcap_prefix,
			    .ring_file_count = m_param.pcap_ring_files,
			    .backlog_trend_threshold = m_param.pcap_backlog_trend_threshold,
		    },
		    .tshark = m_param.tshark,
		    .protocol_map_file = m_param.protocol_map_file,
		    .alert_config_file = m_param.alert_config_file,
	    });

	int rc = 0;
	if(!m_abort) {
		rc = m_monitor->run();
	}

    reporter.stop();

	return rc;
}

//--------------------------------------------------------------------------------
int app::stop() {
	m_abort = true;

	return 0;
}

//--------------------------------------------------------------------------------
std::string app::status() {
	std::string s;

	return s;
}

