}

//--------------------------------------------------------------------------------
int app::parse_options(int argc, char *argv[], app_param *p) {
	cmdline::parser cp;

	cp.add<std::string>("config", 'c', "unified stm config json file", false, "");
	cp.add<int>("debug", 'd', "debug log level", false, 1);
	cp.add<std::string>("name", 'n', "identity name", false, "");
