import type { ReactNode } from "react";

type PaneHeaderProps = {
  title?: ReactNode;
  meta?: ReactNode;
  actions?: ReactNode;
  className?: string;
};

export function PaneHeader({ title, meta, actions, className = "" }: PaneHeaderProps) {
  return (
    <header className={`pane-header ${className}`.trim()}>
      {(title || meta) && (
        <div className="pane-header-copy">
          {title && <strong className="pane-header-title">{title}</strong>}
          {meta && <span className="pane-header-meta">{meta}</span>}
        </div>
      )}
      {actions && <div className="pane-header-actions">{actions}</div>}
    </header>
  );
}


type PaneFrameProps = {
  header: ReactNode;
  children: ReactNode;
  className?: string;
};

export function PaneFrame({ header, children, className = "" }: PaneFrameProps) {
  return (
    <section className={("pane-frame " + className).trim()}>
      {header}
      <div className="pane-body">{children}</div>
    </section>
  );
}
