                    onSelectTime={selectGlobalTime}
                  />
                </section>
              )}
              {activeTab === "events" && (
                <section className="standalone-view standalone-events">
                  <EventLog
                    events={events}
                    eventsRange={eventsRange}
                    onChangeEventsRange={setEventsRange}
                    selectedStreamKey={selectedStreamKey}
                    selectedFlowKey={selectedFlowKey}
                    selectedInterfaceId={selectedInterface?.interfaceId ?? null}
                  />
                </section>
              )}
            </section>
          )}
        </div>
      </div>
      {/* Strong guard against browser history swipe gestures during splitter drags; remove if it interferes with normal dragging. */}
      {resizingPane && <div className={`resize-capture resize-capture-${resizingPane}`} aria-hidden="true" />}
    </main>
  );
}

function titleForDashboardView(viewType: DashboardViewType) {
  switch (viewType) {
    case "streams": return "Streams";
    case "detail": return "Detail";
    case "timeline": return "Timeline";
    case "topology": return "Topology";
    case "events": return "Events";
  }
}

function nextDashboardY(cells: DashboardCell[]) {
  return cells.reduce((max, cell) => Math.max(max, cell.grid.y + cell.grid.h), 0);
}

function clampDashboardCell(cell: DashboardCell, columns: number): DashboardCell {
  const width = Math.max(2, Math.min(columns, Math.round(cell.grid.w)));
  const height = Math.max(3, Math.min(40, Math.round(cell.grid.h)));
  return {
    ...cell,
    title: cell.title || titleForDashboardView(cell.viewType),
    grid: {
      x: Math.max(0, Math.min(columns - width, Math.round(cell.grid.x))),
      y: Math.max(0, Math.min(200, Math.round(cell.grid.y))),
      w: width,
      h: height
    }
  };
}

function compareTimelineRows(a: TimelineRow, b: TimelineRow, streamOrder: Map<string, number>) {
  const positionA = streamOrder.get(a.streamKey);
  const positionB = streamOrder.get(b.streamKey);
  if (positionA !== undefined || positionB !== undefined) {
    if (positionA === undefined) return 1;
    if (positionB === undefined) return -1;
    return positionA - positionB;
  }
  return b.lastSeen - a.lastSeen || a.label.localeCompare(b.label) || a.streamKey.localeCompare(b.streamKey);
}

function timelineRowKey(row: TimelineRow) {
  if (row.rowType === "flow") {
    return `flow:${row.parentStreamKey ?? row.streamKey}::${row.flowKey ?? row.streamKey}`;
  }
  return `stream:${row.streamKey}`;
}

function formatTimeTravel(epochSec: number) {
  return new Date(epochSec * 1000).toLocaleString(undefined, { hour12: false });
}

function standaloneViewFromPath(pathname: string): StandaloneView {
  switch (pathname.replace(/\/+$/, "")) {
    case "/view/streams":
      return "streams";
    case "/view/timeline":
      return "timeline";
    case "/view/events":
      return "events";
    case "/view/detail":
      return "detail";
    default:
      return null;
  }
}

function dashboardCellTextParam(cell: DashboardCell, key: string) {
  const value = cell.params?.[key];
  return typeof value === "string" ? value : "";
}

function dashboardDetailMode(cell: DashboardCell): DetailMode {
  return dashboardCellTextParam(cell, "detailMode") === "detail" ? "detail" : "overview";
}

function dashboardEventsTab(cell: DashboardCell): EventLogTab {
  return dashboardCellTextParam(cell, "eventsTab") === "selected" ? "selected" : "all";
}

function filterStreams(streams: StreamListItem[], query: string) {
  if (!query.trim()) return streams;
  return streams.filter((stream) =>
    matchesSearch([stream.kind, stream.label, stream.streamKey, stream.interfaceName, stream.flowRoles.join(" "), ...stream.flows.map((flow) => flow.interfaceName)], query)
  );
}

function expandLevelFromParam(value: string | null): ExpandLevel {
  return value === "interface" || value === "proto" || value === "flow" || value === "stream" ? value : "stream";
}

function detailModeFromParam(value: string | null): DetailMode {
  return value === "detail" ? "detail" : "overview";
}


function rangeFromParam(value: string | null, fallback: string) {
  return value && RANGE_OPTIONS.includes(value) ? value : fallback;
}

function timelineRangeWindowSec(range: string) {
  switch (range) {
    case "24h":
      return 24 * 3600;
    case "12h":
      return 12 * 3600;
    case "6h":
      return 6 * 3600;
    case "3h":
      return 3 * 3600;
    case "1h":
      return 3600;
    case "30m":
      return 1800;
    case "10m":
      return 600;
    case "5m":
    default:
      return 300;
  }
}


