import { EventEmitter } from "node:events";
import { descriptorForMetric, type NormalizedInterfaceInput, type NormalizedMetricInput, type NormalizedTimelineInput } from "../normalizer";
import type {
  EventLogItem,
  FlowMetricPoint,
  FlowState,
  InterfaceListItem,
  InterfaceMetricsResponse,
  MetricDescriptor,
  MetricPoint,
  NumericStat,
  OverviewStats,
  StreamListItem,
  StreamMetricsResponse,
  StreamState,
  Summary,
  TimelineRow,
  TimeSeriesMetric,
  TopologySnapshot
} from "../types";

export class StreamStore extends EventEmitter {
  private interfaces = new Map<string, InterfaceListItem>();
  private interfaceHistory = new Map<string, FlowMetricPoint[]>();
  private streams = new Map<string, StreamState>();
  private streamSortOrder = new Map<string, number>();
  private lostSinceWall = new Map<string, number>();
  private flowLostSinceWall = new Map<string, number>();
  private flowHistory = new Map<string, FlowMetricPoint[]>();
  private flowSparklines = new Map<string, number[]>();
  private latestUpdate?: number;
  private latestTimelineTime?: number;
  private events: EventLogItem[] = [];
  private eventIds = new Set<string>();
  private timeline = new Map<string, TimelineRow>();
  private eventCountsByStream = new Map<string, number>();
  private eventCountsByStreamOnly = new Map<string, number>();
  private eventCountsByFlow = new Map<string, number>();
  private topology?: TopologySnapshot;

  constructor(
    private readonly historyWindowSec: number,
    private readonly timelineWindowSec: number,
    private readonly staleAfterSec: number,
    private readonly lostRetentionSec: number,
    private readonly maxEvents = 1000,
    private readonly maxTimelineRows = 20000
  ) {
    super();
  }

  applyStreamSnapshot(streams: StreamState[], observedAtWall: number) {
    this.tick(observedAtWall);
    const seen = new Set<string>();
    let changed = streams.length > 0;
    for (const stream of streams) {
      seen.add(stream.streamKey);
      this.lostSinceWall.delete(stream.streamKey);
      this.upsertStream(stream, observedAtWall);
    }

    for (const [streamKey, stream] of this.streams) {
      if (seen.has(streamKey)) continue;
      if (!this.lostSinceWall.has(streamKey)) {
        this.lostSinceWall.set(streamKey, observedAtWall);
        stream.active = false;
        changed = true;
      }
    }

    changed = this.pruneExpiredLostStreams(observedAtWall) || changed;
    if (changed) {
      this.emit("streams:update");
    }
  }

  upsertStream(stream: StreamState, observedAtWall?: number) {
    this.tick(observedAtWall ?? Date.now() / 1000);
    this.attachInterfaceName(stream);
    const existing = this.streams.get(stream.streamKey);
    const mergedFlows = mergeFlows(existing?.flows ?? [], stream.flows, this.flowLostSinceWall, observedAtWall);
    const next: StreamState = {
      ...existing,
      ...stream,
      flows: mergedFlows,
      flowCount: mergedFlows.length,
      flowRoles: [...new Set(mergedFlows.map((flow) => flow.role))],
      bitrate: existing?.bitrate ?? {},
      sparkline: existing?.sparkline ?? []
    };
    this.streams.set(stream.streamKey, next);
    this.latestUpdate = Math.max(this.latestUpdate ?? 0, stream.lastSeen);
    this.lostSinceWall.delete(stream.streamKey);
    this.markStale(observedAtWall ?? Date.now() / 1000);
  }

  upsertInterfaces(items: NormalizedInterfaceInput[]) {
    if (items.length === 0) return;
    this.tick(Date.now() / 1000);
    for (const item of items) {
      const promotedNameKey = item.interfaceId !== undefined ? `name:${item.name}` : undefined;
      const promoted = promotedNameKey && promotedNameKey !== item.key ? this.interfaces.get(promotedNameKey) : undefined;
      const existing = this.interfaces.get(item.key) ?? promoted;
      const rxSparkline = [...(existing?.rxSparkline ?? [])];
      const txSparkline = [...(existing?.txSparkline ?? [])];
      if (item.hasMetrics) {
        rxSparkline.push(item.rxBitrate.value ?? item.rxBitrate.avg ?? 0);
        txSparkline.push(item.txBitrate.value ?? item.txBitrate.avg ?? 0);
        if (rxSparkline.length > 60) rxSparkline.splice(0, rxSparkline.length - 60);
        if (txSparkline.length > 60) txSparkline.splice(0, txSparkline.length - 60);
        const history = [
          ...(this.interfaceHistory.get(item.key) ?? []),
          ...(promotedNameKey && promotedNameKey !== item.key ? this.interfaceHistory.get(promotedNameKey) ?? [] : [])
        ];
        history.push({ time: item.lastSeen ?? Date.now() / 1000, metrics: interfaceMetricsForHistory(item) });
        this.prune(history, item.lastSeen ?? Date.now() / 1000);
        this.interfaceHistory.set(item.key, history);
      }
      if (promotedNameKey && promotedNameKey !== item.key) {
        this.interfaces.delete(promotedNameKey);
        this.interfaceHistory.delete(promotedNameKey);
      }
      this.interfaces.set(item.key, {
        ...existing,
        ...withoutInterfaceMarker(item),
        rx: item.hasMetrics ? item.rx : existing?.rx ?? item.rx,
        tx: item.hasMetrics ? item.tx : existing?.tx ?? item.tx,
        rxBitrate: item.hasMetrics ? item.rxBitrate : existing?.rxBitrate ?? item.rxBitrate,
        txBitrate: item.hasMetrics ? item.txBitrate : existing?.txBitrate ?? item.txBitrate,
        rxSparkline,
        txSparkline,
        streamCount: existing?.streamCount ?? 0
      });
    }
    this.refreshInterfaceNames();
    this.refreshTimelineNames();
    this.emit("streams:update");
  }

  addTimelineEvent(input: NormalizedTimelineInput) {
    this.tick(input.time);
    this.latestTimelineTime = Math.max(this.latestTimelineTime ?? input.time, input.time);
    const row = this.ensureTimelineRow(input);
    row.firstSeen = Math.min(row.firstSeen, input.time);
    row.lastSeen = Math.max(row.lastSeen, input.time);

    if (input.kind === "stream_detected" || input.kind === "stream_recovered" || input.kind === "flow_detected" || input.kind === "flow_recovered") {
      row.active = true;
      const current = row.segments[row.segments.length - 1];
      if (!current || current.end !== null) {
        row.segments.push({ start: input.time, end: null });
      }
    } else if (input.kind === "stream_lost" || input.kind === "flow_lost") {
      row.active = false;
      const current = row.segments[row.segments.length - 1];
      if (current && current.end === null) {
        current.end = input.time;
      } else if (!current) {
        row.segments.push({ start: input.time, end: input.time });
      }
    }

    this.pruneTimeline(this.latestTimelineTime);
    this.enforceTimelineBudget();
    this.emit("timeline:update");
  }

  addMetric(input: NormalizedMetricInput) {
    this.tick(input.time);
    // Lifecycle projection owns identity and active/lost state. A historical raw
    // metric must not recreate a stream or flow that has already been lost.
    const stream = this.streams.get(input.streamKey);
    if (!stream) return;
    const flow = stream.flows.find((item) => item.flowKey === input.flowKey);
    if (!flow) return;
    if (input.interfaceId !== undefined) {
      stream.interfaceId ??= input.interfaceId;
      flow.interfaceId ??= input.interfaceId;
      const interfaceName = this.interfaceById(input.interfaceId)?.name;
      if (interfaceName) {
        stream.interfaceName ??= interfaceName;
        flow.interfaceName ??= interfaceName;
      }
    }
    flow.metrics = input.metrics;
    flow.lastSeen = input.time;

    const history = this.flowHistory.get(input.flowKey) ?? [];
    history.push({ time: input.time, metrics: input.metrics });
    const bitrate = input.metrics.bitrate?.value ?? input.metrics.bitrate?.avg ?? 0;
    const sparkline = this.flowSparklines.get(input.flowKey) ?? [];
    sparkline.push(bitrate);
    if (sparkline.length > 60) sparkline.splice(0, sparkline.length - 60);
    this.flowSparklines.set(input.flowKey, sparkline);
    this.prune(history, input.time);
    this.flowHistory.set(input.flowKey, history);

    this.recomputeStreamBitrate(stream, input.time);
    this.latestUpdate = Math.max(this.latestUpdate ?? 0, input.time);
    this.markStale(input.time);
    this.emit("streams:update");
    this.emit("metrics:update", input.streamKey);
  }


  applyTopologySnapshot(snapshot: TopologySnapshot) {
    this.topology = {
      ...snapshot,
      nodes: snapshot.nodes.map((node) => ({ ...node })),
      edges: snapshot.edges.map((edge) => ({ ...edge }))
    };
    this.emit("topology:update");
  }

  getTopology(): TopologySnapshot | undefined {
    if (!this.topology) return undefined;
    return {
      ...this.topology,
      nodes: this.topology.nodes.map((node) => ({ ...node })),
      edges: this.topology.edges.map((edge) => ({ ...edge }))
    };
  }

  listStreams(): StreamListItem[] {
    const ordered = [...this.streams.values()]
      .sort((a, b) => compareStreamsStable(a, b, this.streamSortOrder))
      .map((stream) => ({
        ...stream,
        overview: this.overviewForStream(stream),
        flows: stream.flows.map((flow) => ({
          flowKey: flow.flowKey,
          role: flow.role,
          label: flow.label,
          active: flow.active,
          interfaceId: flow.interfaceId,
          interfaceName: flow.interfaceName,
          endpointSrc: flow.endpointSrc,
          endpointDst: flow.endpointDst,
          lastSeen: flow.lastSeen,
          bitrate: flow.metrics.bitrate ?? {},
          sparkline: this.flowSparklines.get(flow.flowKey) ?? [],
          overview: this.overviewForFlow(flow, stream.streamKey)
        }))
      }));

    ordered.forEach((stream, index) => this.streamSortOrder.set(stream.streamKey, index));
    return ordered;
  }

  listInterfaces(): InterfaceListItem[] {
    const streamCounts = new Map<number, number>();
    for (const stream of this.streams.values()) {
      if (stream.interfaceId !== undefined) {
        streamCounts.set(stream.interfaceId, (streamCounts.get(stream.interfaceId) ?? 0) + 1);
      }
    }
    return [...this.interfaces.values()]
      .map((item) => ({ ...item, streamCount: item.interfaceId !== undefined ? streamCounts.get(item.interfaceId) ?? 0 : 0 }))
      .sort((a, b) => (a.interfaceId ?? Number.MAX_SAFE_INTEGER) - (b.interfaceId ?? Number.MAX_SAFE_INTEGER) || a.name.localeCompare(b.name));
  }

  listTimeline(): TimelineRow[] {
    const order = [...this.streams.values()]
      .sort((a, b) => compareStreamsStable(a, b, this.streamSortOrder))
      .map((stream) => stream.streamKey);
    const positions = new Map(order.map((streamKey, index) => [streamKey, index]));
    return [...this.timeline.values()]
      .map((row) => ({
        ...row,
        segments: row.segments.map((segment) => ({ ...segment }))
      }))
      .sort((a, b) => {
        const parentA = a.parentStreamKey ?? a.streamKey;
        const parentB = b.parentStreamKey ?? b.streamKey;
        const positionA = positions.get(parentA);
        const positionB = positions.get(parentB);
        if (positionA !== undefined || positionB !== undefined) {
          if (positionA === undefined) return 1;
          if (positionB === undefined) return -1;
          if (positionA !== positionB) return positionA - positionB;
          if (a.rowType !== b.rowType) return a.rowType === "stream" ? -1 : 1;
          return (a.flowKey ?? a.streamKey).localeCompare(b.flowKey ?? b.streamKey);
        }
        return b.lastSeen - a.lastSeen || a.label.localeCompare(b.label) || (a.flowKey ?? a.streamKey).localeCompare(b.flowKey ?? b.streamKey);
      });
  }

  getInterfaceMetrics(interfaceId: number, windowSec = this.historyWindowSec): InterfaceMetricsResponse | undefined {
    return this.getInterfaceMetricsByKey(`if:${interfaceId}`, windowSec);
  }

  getInterfaceMetricsByKey(key: string, windowSec = this.historyWindowSec): InterfaceMetricsResponse | undefined {
    const item = this.interfaces.get(key);
    if (!item) return undefined;

    const since = (this.latestUpdate ?? item.lastSeen ?? Date.now() / 1000) - windowSec;
    const history = (this.interfaceHistory.get(item.key) ?? []).filter((point) => point.time >= since);
    const metricKeys = new Set<string>();
    const metrics = buildMetrics(history, metricKeys);

    return {
      key: item.key,
      interfaceId: item.interfaceId,
      name: item.name,
      windowSec,
      metrics
    };
  }

  getStream(streamKey: string) {
    return this.streams.get(streamKey);
  }

  getMetrics(streamKey: string, windowSec = this.historyWindowSec): StreamMetricsResponse | undefined {
    const stream = this.streams.get(streamKey);
    if (!stream) return undefined;

    const since = (this.latestUpdate ?? Date.now() / 1000) - windowSec;
    const metricKeys = new Set<string>();
    const flows = stream.flows.map((flow) => {
      const history = (this.flowHistory.get(flow.flowKey) ?? []).filter((point) => point.time >= since);
      const metrics = buildMetrics(history, metricKeys);
      return {
        flowKey: flow.flowKey,
        role: flow.role,
        label: flow.label,
        endpointSrc: flow.endpointSrc,
        endpointDst: flow.endpointDst,
        metrics
      };
    });

    const streamBitrate = this.buildStreamBitrate(stream, since);
    metricKeys.add("bitrate");

    const descriptors = [...metricKeys]
      .map(descriptorForMetric)
      .sort((a, b) => a.priority - b.priority || a.label.localeCompare(b.label));

    return {
      streamKey,
      windowSec,
      streamBitrate,
      flows,
      descriptors
    };
  }

  addEvent(event: EventLogItem) {
    if (this.eventIds.has(event.id)) return;
    this.events.push(event);
    this.eventIds.add(event.id);
    this.incrementEventCounts(event, 1);
    if (this.events.length > this.maxEvents) {
      const removed = this.events.splice(0, this.events.length - this.maxEvents);
      for (const item of removed) {
        this.eventIds.delete(item.id);
        this.incrementEventCounts(item, -1);
      }
    }
    this.emit("events:update", event);
  }

  listEvents(options: { streamKey?: string; flowKey?: string; interfaceId?: number; limit?: number } = {}) {
    const limit = Math.max(1, Math.min(options.limit ?? 100, this.maxEvents));
    return this.events
      .filter((event) => {
        if (options.flowKey) return event.flowKey === options.flowKey || event.streamKey === options.streamKey;
        if (options.streamKey) return event.streamKey === options.streamKey;
        if (options.interfaceId !== undefined) return event.interfaceId === options.interfaceId;
        return true;
      })
      .slice(-limit)
      .reverse();
  }

  getSummary(): Summary {
    const byKind: Record<string, number> = {};
    let activeStreams = 0;
    for (const stream of this.streams.values()) {
      byKind[stream.kind] = (byKind[stream.kind] ?? 0) + 1;
      if (stream.active) activeStreams += 1;
    }
    return {
      totalStreams: this.streams.size,
      activeStreams,
      updatedAt: this.latestUpdate,
      byKind
    };
  }

  private ensureStream(input: NormalizedMetricInput): StreamState {
    const existing = this.streams.get(input.streamKey);
    if (existing) return existing;

    const stream: StreamState = {
      streamKey: input.streamKey,
      kind: inferKind(input.streamKey),
      proto: inferKind(input.streamKey),
      label: input.streamKey,
      interfaceId: input.interfaceId,
      interfaceName: input.interfaceId !== undefined ? this.interfaceById(input.interfaceId)?.name : undefined,
      active: true,
      lastSeen: input.time,
      flowCount: 0,
      flowRoles: [],
      bitrate: {},
      sparkline: [],
      flows: []
    };
    this.streams.set(input.streamKey, stream);
    return stream;
  }

  private ensureFlow(stream: StreamState, input: NormalizedMetricInput): FlowState {
    let flow = stream.flows.find((item) => item.flowKey === input.flowKey);
    if (!flow) {
      flow = {
        flowKey: input.flowKey,
        role: input.role,
        label: input.label,
        active: true,
        interfaceId: input.interfaceId ?? stream.interfaceId,
        interfaceName: (input.interfaceId ?? stream.interfaceId) !== undefined ? this.interfaceById((input.interfaceId ?? stream.interfaceId)!)?.name : stream.interfaceName,
        endpointSrc: input.endpointSrc,
        endpointDst: input.endpointDst,
        lastSeen: input.time,
        metrics: {}
      };
      stream.flows.push(flow);
    } else {
      flow.role = input.role;
      flow.label = input.label;
      flow.interfaceId = input.interfaceId ?? flow.interfaceId ?? stream.interfaceId;
      if (flow.interfaceId !== undefined) flow.interfaceName = this.interfaceById(flow.interfaceId)?.name ?? flow.interfaceName;
      flow.endpointSrc = input.endpointSrc ?? flow.endpointSrc;
      flow.endpointDst = input.endpointDst ?? flow.endpointDst;
    }
    this.flowLostSinceWall.delete(flow.flowKey);
    stream.flowCount = stream.flows.length;
    stream.flowRoles = [...new Set(stream.flows.map((item) => item.role))];
    stream.lastSeen = Math.max(stream.lastSeen, input.time);
    return flow;
  }

  private recomputeStreamBitrate(stream: StreamState, time: number) {
    const bitrateStats = stream.flows.map((flow) => flow.metrics.bitrate).filter(Boolean) as NumericStat[];
    const value = sumStat(bitrateStats, "value");
    const avg = sumStat(bitrateStats, "avg");
    const min = sumStat(bitrateStats, "min");
    const max = sumStat(bitrateStats, "max");
    stream.bitrate = { value, avg, min, max };
    stream.sparkline.push(value ?? avg ?? 0);
    if (stream.sparkline.length > 60) stream.sparkline.splice(0, stream.sparkline.length - 60);
    stream.lastSeen = Math.max(stream.lastSeen, time);
  }

  private buildStreamBitrate(stream: StreamState, since: number): TimeSeriesMetric {
    const times = new Set<number>();
    for (const flow of stream.flows) {
      for (const point of this.flowHistory.get(flow.flowKey) ?? []) {
        if (point.time >= since) times.add(point.time);
      }
    }

    const points = [...times].sort((a, b) => a - b).map((time): MetricPoint => {
      const stats = stream.flows
        .map((flow) => nearestMetric(this.flowHistory.get(flow.flowKey) ?? [], time, "bitrate"))
        .filter(Boolean) as NumericStat[];
      return {
        time,
        value: sumStat(stats, "value"),
        avg: sumStat(stats, "avg"),
        min: sumStat(stats, "min"),
        max: sumStat(stats, "max")
      };
    });

    return { key: "bitrate", label: "Stream Bitrate", unit: "bps", points };
  }

  private prune(history: FlowMetricPoint[], now: number) {
    const cutoff = now - this.historyWindowSec;
    let removeCount = 0;
    while (removeCount < history.length && history[removeCount].time < cutoff) removeCount += 1;
    if (removeCount > 0) history.splice(0, removeCount);
  }

  tick(nowWall = Date.now() / 1000) {
    this.pruneExpiredLostStreams(nowWall);
    this.markStale(nowWall);
  }

  private markStale(nowWall: number) {
    for (const stream of this.streams.values()) {
      stream.active = !this.lostSinceWall.has(stream.streamKey) && nowWall - stream.lastSeen <= this.staleAfterSec;
      for (const flow of stream.flows) {
        flow.active = !this.flowLostSinceWall.has(flow.flowKey) && nowWall - flow.lastSeen <= this.staleAfterSec;
      }
    }
  }

  private pruneExpiredLostStreams(nowWall: number) {
    let changed = false;
    for (const stream of this.streams.values()) {
      const retainedFlows: FlowState[] = [];
      for (const flow of stream.flows) {
        const lostSince = this.flowLostSinceWall.get(flow.flowKey);
        if (lostSince !== undefined && nowWall - lostSince >= this.lostRetentionSec) {
          this.flowLostSinceWall.delete(flow.flowKey);
          this.flowHistory.delete(flow.flowKey);
          this.flowSparklines.delete(flow.flowKey);
          changed = true;
          continue;
        }
        retainedFlows.push(flow);
      }
      if (retainedFlows.length !== stream.flows.length) {
        stream.flows = retainedFlows;
        stream.flowCount = retainedFlows.length;
        stream.flowRoles = [...new Set(retainedFlows.map((flow) => flow.role))];
      }
    }

    for (const [streamKey, lostSince] of this.lostSinceWall) {
      if (nowWall - lostSince < this.lostRetentionSec) continue;
      this.lostSinceWall.delete(streamKey);
      const stream = this.streams.get(streamKey);
      if (stream) {
        for (const flow of stream.flows) {
          this.flowLostSinceWall.delete(flow.flowKey);
          this.flowHistory.delete(flow.flowKey);
          this.flowSparklines.delete(flow.flowKey);
        }
      }
      this.streams.delete(streamKey);
      changed = true;
    }
    this.pruneStreamSortOrder();
    return changed;
  }

  private pruneTimeline(now: number) {
    const cutoff = now - this.timelineWindowSec;
    for (const [key, row] of this.timeline) {
      const retained = row.segments
        .map((segment) => {
          const effectiveEnd = segment.end ?? now;
          if (effectiveEnd <= cutoff) return undefined;
          return {
            start: Math.max(segment.start, cutoff),
            end: segment.end
          };
        })
        .filter((segment): segment is NonNullable<typeof segment> => segment !== undefined);

      if (retained.length === 0 && row.lastSeen <= cutoff && !row.active) {
        this.timeline.delete(key);
        continue;
      }

      row.segments = retained;
      if (retained.length > 0) {
        row.firstSeen = retained[0].start;
      }
    }
  }

  private enforceTimelineBudget() {
    if (this.timeline.size <= this.maxTimelineRows) return;

    const removable = [...this.timeline.entries()]
      .filter(([, row]) => !row.active)
      .sort((a, b) => a[1].lastSeen - b[1].lastSeen);

    for (const [key] of removable) {
      if (this.timeline.size <= this.maxTimelineRows) break;
      this.timeline.delete(key);
    }

    if (this.timeline.size <= this.maxTimelineRows) return;

    const forced = [...this.timeline.entries()]
      .sort((a, b) => {
        if (a[1].rowType !== b[1].rowType) {
          return a[1].rowType === "flow" ? -1 : 1;
        }
        return a[1].lastSeen - b[1].lastSeen;
      });

    for (const [key] of forced) {
      if (this.timeline.size <= this.maxTimelineRows) break;
      this.timeline.delete(key);
    }
  }

  private pruneStreamSortOrder() {
    for (const streamKey of this.streamSortOrder.keys()) {
      if (!this.streams.has(streamKey)) this.streamSortOrder.delete(streamKey);
    }
  }

  private overviewForStream(stream: StreamState): OverviewStats {
    const stats = stream.flows.map((flow) => this.overviewForFlow(flow, stream.streamKey));
    return {
      gap: sumOverview(stats, "gap"),
      dup: sumOverview(stats, "dup"),
      reorder: sumOverview(stats, "reorder"),
      events: this.eventCountsByStream.get(stream.streamKey) ?? 0
    };
  }

  private overviewForFlow(flow: FlowState, streamKey: string): OverviewStats {
    return {
      gap: statValue(flow.metrics["seq_stats.gap"]),
      dup: statValue(flow.metrics["seq_stats.dup"]),
      reorder: statValue(flow.metrics["seq_stats.reorder"]),
      events: (this.eventCountsByFlow.get(flow.flowKey) ?? 0) + (this.eventCountsByStreamOnly.get(streamKey) ?? 0)
    };
  }
import { readFile, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import type { FastifyInstance } from "fastify";
import type { StreamStore } from "../state/store";
import { config } from "../config";
import { queryInterfaceMetricsHistory, queryMetricsSnapshotAt, queryStreamMetricsHistory } from "../history/query";
import { queryTimelineHistory } from "../history/timeline_query";
import { queryEventsHistory } from "../history/events_query";
import { queryProjectedTopologyAt } from "../history/topology_state_query";
import { enrichProjectedStreamSnapshot, queryProjectedStreamsAt } from "../history/stream_state_query";
import type { DashboardLayout, TimelineRow, TimelineViewResponse } from "../types";

export async function registerRoutes(app: FastifyInstance, store: StreamStore) {
  app.addHook("onSend", async (_request, reply, payload) => {
    reply.header("Cache-Control", "no-store");
    return payload;
  });

  app.get("/api/config", async () => ({
    lostRetentionSec: config.lostRetentionSec,
    historyWindowSec: config.historyWindowSec,
    staleAfterSec: config.staleAfterSec
  }));

  app.get("/api/summary", async () => store.getSummary());

  app.get("/api/dashboard-layouts", async () => readDashboardLayouts());

  app.put<{ Body: DashboardLayout[] }>("/api/dashboard-layouts", async (request) => {
    const layouts = Array.isArray(request.body) ? request.body : [DEFAULT_DASHBOARD_LAYOUT];
    await writeDashboardLayouts(layouts);
    return readDashboardLayouts();
  });


  app.get("/api/bootstrap", async () => ({
    streams: store.listStreams(),
    interfaces: store.listInterfaces(),
    timeline: store.listTimeline(),
    summary: store.getSummary(),
    events: store.listEvents({ limit: 100 })
  }));

  app.get("/api/interfaces", async () => store.listInterfaces());

  app.get<{ Params: { interfaceId: string }; Querystring: { windowSec?: string; from?: string; to?: string } }>(
    "/api/interfaces/:interfaceId/metrics",
    async (request, reply) => {
      const interfaceId = Number(request.params.interfaceId);
      const windowSec = request.query.windowSec ? Number(request.query.windowSec) : undefined;
      if (!Number.isInteger(interfaceId)) return reply.code(400).send({ error: "invalid interface id" });
      const metrics = store.getInterfaceMetrics(interfaceId, Number.isFinite(windowSec) ? windowSec : undefined);
      if (!metrics) return reply.code(404).send({ error: "interface not found" });
      return metrics;
    }
  );

  app.get<{ Params: { key: string }; Querystring: { windowSec?: string; from?: string; to?: string } }>(
    "/api/interfaces/by-key/:key/metrics",
    async (request, reply) => {
      const key = decodeURIComponent(request.params.key);
      const windowSec = request.query.windowSec ? Number(request.query.windowSec) : undefined;
      const from = request.query.from ? Number(request.query.from) : undefined;
      const to = request.query.to ? Number(request.query.to) : undefined;
      if (Number.isFinite(from) && Number.isFinite(to) && to! > from!) {
        const metrics = await queryInterfaceMetricsHistory({ key, from: from!, to: to! });
        if (!metrics) return reply.code(404).send({ error: "interface history not available" });
        return metrics;
      }
      const metrics = store.getInterfaceMetricsByKey(key, Number.isFinite(windowSec) ? windowSec : undefined);
      if (!metrics) return reply.code(404).send({ error: "interface not found" });
      return metrics;
    }
  );

  app.get<{ Querystring: { time?: string } }>("/api/streams", async (request, reply) => {
    const time = request.query.time ? Number(request.query.time) : undefined;
    if (Number.isFinite(time)) {
      let snapshot = await queryProjectedStreamsAt(config.streamStateDir, time!);
      if (!snapshot) return reply.code(404).send({ error: "streams snapshot not available" });
      const metricsSnapshot = await queryMetricsSnapshotAt(time!);
      if (metricsSnapshot) snapshot = enrichProjectedStreamSnapshot(snapshot, metricsSnapshot.interfaces, metricsSnapshot.metrics);
      return snapshot;
    }
    return store.listStreams();
  });

  app.get<{ Querystring: { time?: string } }>("/api/topology", async (request, reply) => {
    const time = request.query.time ? Number(request.query.time) : undefined;
    if (Number.isFinite(time)) {
      const snapshot = await queryProjectedTopologyAt({
        checkpointDir: config.topologyCheckpointDir,
        updatesDir: config.topologyUpdatesDir,
        time: time!
      });
      if (!snapshot) return reply.code(404).send({ error: "topology snapshot not available" });
      return snapshot;
    }
    const topology = store.getTopology();
    if (config.diagnosticLog) console.error("[STM_DIAG] api topology status=" + (topology ? "200" : "404") + " nodes=" + (topology?.nodes.length ?? 0) + " edges=" + (topology?.edges.length ?? 0));
    if (!topology) return reply.code(404).send({ error: "topology snapshot not available" });
    return topology;
  });

  app.get<{ Querystring: { from?: string; to?: string; includeFlows?: string } }>("/api/timeline", async (request): Promise<TimelineViewResponse> => {
    const from = request.query.from ? Number(request.query.from) : undefined;
    const to = request.query.to ? Number(request.query.to) : undefined;
    if (Number.isFinite(from) && Number.isFinite(to) && to! > from!) {
      return queryTimelineHistory({
        from: from!,
        to: to!,
        includeFlows: request.query.includeFlows !== "0"
      });
    }
    const rows = store.listTimeline();
    const bounds = timelineBounds(rows);
    return {
      rows,
      window: bounds,
      available: bounds,
      source: "live"
    };
  });

  app.get<{ Querystring: { streamKey?: string; flowKey?: string; interfaceId?: string; limit?: string; from?: string; to?: string; proto?: string; level?: string; type?: string } }>("/api/events", async (request) => {
    const limit = request.query.limit ? Number(request.query.limit) : undefined;
    const interfaceId = request.query.interfaceId ? Number(request.query.interfaceId) : undefined;
    const from = request.query.from ? Number(request.query.from) : undefined;
    const to = request.query.to ? Number(request.query.to) : undefined;
    const level = request.query.level;
    if (Number.isFinite(from) && Number.isFinite(to) && to! > from!) {
      const result = await queryEventsHistory({
        from: from!,
        to: to!,
        streamKey: request.query.streamKey,
        flowKey: request.query.flowKey,
        interfaceId: Number.isInteger(interfaceId) ? interfaceId : undefined,
        proto: request.query.proto,
        level: level === "info" || level === "warn" || level === "error" ? level : undefined,
        type: request.query.type,
        limit: Number.isFinite(limit) ? limit : undefined
      });
      if (config.diagnosticLog) console.error("[STM_DIAG] api events range=" + from + "-" + to + " result=" + result.length + " journal=" + config.eventJournalDir);
      return result;
    }
    const result = store.listEvents({
      streamKey: request.query.streamKey,
      flowKey: request.query.flowKey,
      interfaceId: Number.isInteger(interfaceId) ? interfaceId : undefined,
      limit: Number.isFinite(limit) ? limit : undefined
    });
    if (config.diagnosticLog) console.error("[STM_DIAG] api events live result=" + result.length + " journal=" + config.eventJournalDir);
    return result;
  });

  app.get<{ Params: { streamKey: string } }>("/api/streams/:streamKey", async (request, reply) => {
    const stream = store.getStream(decodeURIComponent(request.params.streamKey));
    if (!stream) return reply.code(404).send({ error: "stream not found" });
    return stream;
  });

  app.get<{ Params: { streamKey: string }; Querystring: { windowSec?: string; from?: string; to?: string; resolutionSec?: string } }>(
    "/api/streams/:streamKey/metrics",
    async (request, reply) => {
      const streamKey = decodeURIComponent(request.params.streamKey);
      const from = request.query.from ? Number(request.query.from) : undefined;
      const to = request.query.to ? Number(request.query.to) : undefined;
      const resolutionSec = request.query.resolutionSec ? Number(request.query.resolutionSec) : undefined;
      if (Number.isFinite(from) && Number.isFinite(to) && to! > from!) {
        return queryStreamMetricsHistory({
          streamKey,
          from: from!,
          to: to!,
          resolutionSec: Number.isFinite(resolutionSec) ? resolutionSec : undefined
        });
      }
      const windowSec = request.query.windowSec ? Number(request.query.windowSec) : undefined;
      const metrics = store.getMetrics(streamKey, Number.isFinite(windowSec) ? windowSec : undefined);
      if (!metrics) return reply.code(404).send({ error: "stream not found" });
      return metrics;
    }
  );
}

function timelineBounds(rows: TimelineRow[]) {
  if (rows.length === 0) {
    const now = Date.now() / 1000;
    return { from: now - 300, to: now };
  }

  let from = Number.POSITIVE_INFINITY;
  let to = Number.NEGATIVE_INFINITY;
  for (const row of rows) {
    from = Math.min(from, row.firstSeen, ...row.segments.map((segment) => segment.start));
    to = Math.max(to, row.lastSeen, ...row.segments.map((segment) => segment.end ?? row.lastSeen));
  }

  if (!Number.isFinite(from) || !Number.isFinite(to) || to <= from) {
    const now = Date.now() / 1000;
    return { from: now - 300, to: now };
  }

  return { from, to };
}


