export async function getEvents(params: {
  streamKey?: string;
  flowKey?: string;
  interfaceId?: number;
  limit?: number;
  from?: number;
  to?: number;
  proto?: string;
  level?: "info" | "warn" | "error";
  type?: string;
} = {}): Promise<EventLogItem[]> {
  const query = new URLSearchParams();
  if (params.streamKey) query.set("streamKey", params.streamKey);
  if (params.flowKey) query.set("flowKey", params.flowKey);
  if (params.interfaceId !== undefined) query.set("interfaceId", String(params.interfaceId));
  if (params.from !== undefined) query.set("from", String(params.from));
  if (params.to !== undefined) query.set("to", String(params.to));
  if (params.proto) query.set("proto", params.proto);
  if (params.level) query.set("level", params.level);
  if (params.type) query.set("type", params.type);
  if (params.limit) query.set("limit", String(params.limit));
  const suffix = query.toString() ? `?${query.toString()}` : "";
  return getJson(`/api/events${suffix}`);
}

async function getJson<T>(url: string): Promise<T> {
  const response = await fetch(url, { cache: "no-store" });
  if (!response.ok) throw new Error(`${response.status} ${response.statusText}`);
  return response.json() as Promise<T>;
