+        if (setting[field] !== undefined && (!Number.isInteger(setting[field]) || Number(setting[field]) < 0)) throw new Error(`invalid ${field}: ${key}`);
+      }
+      if (setting.min !== undefined && setting.max !== undefined && Number(setting.min) > Number(setting.max)) throw new Error(`invalid range: ${key}`);
+      seen.add(key);
+      return {
+        key: key as keyof RuntimeSettings,
+        label: setting.label,
+        description: typeof setting.description === "string" ? setting.description : undefined,
+        type: setting.type,
+        unit: typeof setting.unit === "string" ? setting.unit : undefined,
+        min: typeof setting.min === "number" ? setting.min : undefined,
+        max: typeof setting.max === "number" ? setting.max : undefined,
+        step: typeof setting.step === "number" ? setting.step : undefined,
+        options: Array.isArray(setting.options) ? setting.options.filter(isOption) : undefined,
+        apply: setting.apply as SettingDefinition["apply"]
+      };
+    });
+    return { id: section.id, label: section.label, description: typeof section.description === "string" ? section.description : undefined, settings };
+  });
+  if (seen.size !== allowedKeys.size) throw new Error("definition must include every supported setting");
+  return { version: root.version, sections };
+}
+
+function isOption(value: unknown): value is { value: number; label: string } {
+  return Boolean(value) && typeof value === "object" && !Array.isArray(value)
+    && Number.isInteger((value as { value?: unknown }).value) && typeof (value as { label?: unknown }).label === "string";
+}
