import { existsSync } from "node:fs";
import { readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";

export type RuntimeSettings = {
  lostRetentionSec: number;
  historyWindowSec: number;
  staleAfterSec: number;
};

export type MaintenanceSetting = {
  key: keyof RuntimeSettings;
  label: string;
  description?: string;
  type: "integer" | "select";
  unit?: string;
  min?: number;
  max?: number;
  step?: number;
  options?: Array<{ value: number; label: string }>;
  apply: "live" | "next-input" | "restart" | "manual";
};

type SettingsDefinition = {
  version: number;
  sections: Array<{ id: string; label: string; description?: string; settings: MaintenanceSetting[] }>;
};

export type MaintenanceSettingsResponse = {
  revision: number;
  sections: SettingsDefinition["sections"];
  values: RuntimeSettings;
};

export class SettingsConflictError extends Error {}
export class SettingsValidationError extends Error {}

