import { existsSync } from "node:fs";
import { readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";

export type RuntimeSettings = {
  lostRetentionSec: number;
  historyWindowSec: number;
  staleAfterSec: number;
};

export type MaintenanceSetting = {
  key: keyof RuntimeSettings;
  label: string;
  description?: string;
  type: "integer" | "select";
  unit?: string;
  min?: number;
  max?: number;
  step?: number;
  options?: Array<{ value: number; label: string }>;
  apply: "live" | "next-input" | "restart" | "manual";
};

type SettingsDefinition = {
  version: number;
  sections: Array<{ id: string; label: string; description?: string; settings: MaintenanceSetting[] }>;
};

export type MaintenanceSettingsResponse = {
  revision: number;
  sections: SettingsDefinition["sections"];
  values: RuntimeSettings;
};

export class SettingsConflictError extends Error {}
export class SettingsValidationError extends Error {}

export class MaintenanceSettings {
  private revision = 0;
  private values: RuntimeSettings;
  private writeQueue = Promise.resolve();

  private constructor(
    private readonly definition: SettingsDefinition,
    private readonly runtimeFile: string,
    defaults: RuntimeSettings
  ) {
    this.values = { ...defaults };
  }

  static async load(options: { definitionFile: string; runtimeFile: string; defaults: RuntimeSettings }) {
    const definition = parseDefinition(JSON.parse(await readFile(options.definitionFile, "utf8")));
    const settings = new MaintenanceSettings(definition, options.runtimeFile, options.defaults);
    if (!existsSync(options.runtimeFile)) return settings;

    try {
      const persisted = JSON.parse(await readFile(options.runtimeFile, "utf8")) as { revision?: unknown; values?: unknown };
      settings.values = settings.validateValues(persisted.values);
      settings.revision = Number.isInteger(persisted.revision) && Number(persisted.revision) >= 0 ? Number(persisted.revision) : 0;
    } catch (error) {
      console.warn(`maintenance settings: ignoring invalid runtime file ${options.runtimeFile}: ${String(error)}`);
    }
    return settings;
  }

  get(): MaintenanceSettingsResponse {
    return { revision: this.revision, sections: this.definition.sections, values: { ...this.values } };
  }

  update(revision: unknown, values: unknown) {
    const operation = this.writeQueue.then(async () => {
      if (!Number.isInteger(revision) || Number(revision) !== this.revision) {
        throw new SettingsConflictError("settings changed on the server; reload before saving");
      }
      const next = this.validateValues(values);
      const nextRevision = this.revision + 1;
      const temporary = path.join(path.dirname(this.runtimeFile), `.${path.basename(this.runtimeFile)}.${process.pid}.tmp`);
      await writeFile(temporary, `${JSON.stringify({ version: 1, revision: nextRevision, values: next }, null, 2)}\n`, "utf8");
      await rename(temporary, this.runtimeFile);
      this.values = next;
      this.revision = nextRevision;
      return this.get();
    });
    this.writeQueue = operation.then(() => undefined, () => undefined);
    return operation;
  }

  private validateValues(input: unknown): RuntimeSettings {
    if (!input || typeof input !== "object" || Array.isArray(input)) throw new SettingsValidationError("values must be an object");
    const source = input as Record<string, unknown>;
    const definitions = this.definition.sections.flatMap((section) => section.settings);
    const expected = new Set(definitions.map((setting) => setting.key));
    for (const key of Object.keys(source)) {
      if (!expected.has(key as keyof RuntimeSettings)) throw new SettingsValidationError(`unknown setting: ${key}`);
    }
    const result = {} as RuntimeSettings;
    for (const setting of definitions) {
      const value = source[setting.key];
      if (typeof value !== "number" || !Number.isInteger(value)) throw new SettingsValidationError(` must be an integer`);
      if (setting.min !== undefined && value < setting.min) throw new SettingsValidationError(`${setting.key} must be at least ${setting.min}`);
      if (setting.max !== undefined && value > setting.max) throw new SettingsValidationError(`${setting.key} must be at most ${setting.max}`);
      if (setting.options && !setting.options.some((option) => option.value === value)) throw new SettingsValidationError(`${setting.key} is not an allowed value`);
      result[setting.key] = value;
    }
    return result;
  }
}

function parseDefinition(input: unknown): SettingsDefinition {
  if (!input || typeof input !== "object" || Array.isArray(input)) throw new Error("definition must be an object");
  const root = input as Record<string, unknown>;
  if (!Number.isInteger(root.version) || !Array.isArray(root.sections)) throw new Error("definition version and sections are required");
  const supported = new Set<keyof RuntimeSettings>(["lostRetentionSec", "historyWindowSec", "staleAfterSec"]);
  const seen = new Set<string>();
  const sections = root.sections.map((rawSection) => {
    if (!rawSection || typeof rawSection !== "object" || Array.isArray(rawSection)) throw new Error("invalid section");
    const section = rawSection as Record<string, unknown>;
    if (typeof section.id !== "string" || typeof section.label !== "string" || !Array.isArray(section.settings)) throw new Error("section id, label, and settings are required");
    const settings = section.settings.map((rawSetting) => {
      if (!rawSetting || typeof rawSetting !== "object" || Array.isArray(rawSetting)) throw new Error("invalid setting");
      const setting = rawSetting as Record<string, unknown>;
      const key = setting.key;
      if (typeof key !== "string" || !supported.has(key as keyof RuntimeSettings) || seen.has(key)) throw new Error(`invalid setting key: ${String(key)}`);
      if (typeof setting.label !== "string" || (setting.type !== "integer" && setting.type !== "select") || !["live", "next-input", "restart", "manual"].includes(String(setting.apply))) throw new Error(`invalid setting: ${key}`);
      for (const field of ["min", "max", "step"] as const) {
        if (setting[field] !== undefined && (!Number.isInteger(setting[field]) || Number(setting[field]) < 0)) throw new Error(`invalid ${field}: ${key}`);
      }
      if (setting.min !== undefined && setting.max !== undefined && Number(setting.min) > Number(setting.max)) throw new Error(`invalid range: ${key}`);
      seen.add(key);
      return {
        key: key as keyof RuntimeSettings,
        label: setting.label,
        description: typeof setting.description === "string" ? setting.description : undefined,
        type: setting.type as MaintenanceSetting["type"],
        unit: typeof setting.unit === "string" ? setting.unit : undefined,
        min: typeof setting.min === "number" ? setting.min : undefined,
        max: typeof setting.max === "number" ? setting.max : undefined,
        step: typeof setting.step === "number" ? setting.step : undefined,
        options: Array.isArray(setting.options) ? setting.options.filter(isOption) : undefined,
        apply: setting.apply as MaintenanceSetting["apply"]
      };
    });
    return { id: section.id, label: section.label, description: typeof section.description === "string" ? section.description : undefined, settings };
  });
  if (seen.size !== supported.size) throw new Error("definition must include every supported setting");
  return { version: Number(root.version), sections };
}

function isOption(value: unknown): value is { value: number; label: string } {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value)
    && Number.isInteger((value as { value?: unknown }).value) && typeof (value as { label?: unknown }).label === "string";
}
import { useEffect, useState, type FormEvent } from "react";
import { getMaintenanceSettings, saveMaintenanceSettings } from "../api/client";
import type { AppConfig, MaintenanceSettingsResponse } from "../types/api";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

type MaintenancePaneProps = {
  refreshToken: number;
  onApplied: (config: AppConfig) => void;
};

export function MaintenancePane({ refreshToken, onApplied }: MaintenancePaneProps) {
  const [settings, setSettings] = useState<MaintenanceSettingsResponse | null>(null);
  const [draft, setDraft] = useState<AppConfig | null>(null);
  const [state, setState] = useState<"loading" | "idle" | "saving" | "saved" | "error">("loading");
  const [message, setMessage] = useState("");

  useEffect(() => {
    let cancelled = false;
    setState("loading");
    void getMaintenanceSettings().then((next) => {
      if (cancelled) return;
      setSettings(next);
      setDraft(next.values);
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      if (cancelled) return;
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load settings");
    });
    return () => { cancelled = true; };
  }, [refreshToken]);

  const reload = () => {
    setState("loading");
    void getMaintenanceSettings().then((next) => {
      setSettings(next);
      setDraft(next.values);
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load settings");
    });
  };

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings || !draft) return;
    setState("saving");
    setMessage("");
    void saveMaintenanceSettings(settings.revision, draft).then((next) => {
      setSettings(next);
      setDraft(next.values);
      onApplied(next.values);
      setState("saved");
      setMessage("Saved and applied to all connected clients.");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to save settings");
    });
  };

  return (
    <PaneFrame
      className="maintenance-frame"
      header={<PaneHeader
        title="Maintenance"
        meta="Shared frontend runtime settings"
        actions={<button type="button" className="maintenance-secondary-button" onClick={reload} disabled={state === "loading" || state === "saving"}>Reload</button>}
      />}
    >
      <form className="maintenance-form" onSubmit={submit}>
        <div className="maintenance-intro">Changes are validated by the server, persisted for the next restart, and applied immediately to every connected client.</div>
        {settings?.sections.map((section) => (
          <section key={section.id} className="maintenance-section">
            <div className="maintenance-section-copy">
              <h2>{section.label}</h2>
              {section.description && <p>{section.description}</p>}
            </div>
            <div className="maintenance-table-wrap">
              <table className="maintenance-table">
                <thead><tr><th>Parameter</th><th>Value</th><th>Range</th><th>Apply</th></tr></thead>
                <tbody>
                  {section.settings.map((setting) => (
                    <tr key={setting.key}>
                      <th scope="row"><span>{setting.label}</span>{setting.description && <small>{setting.description}</small>}</th>
                      <td>
                        {setting.type === "select" ? (
                          <select value={draft?.[setting.key] ?? ""} disabled={!draft || state === "saving"} onChange={(event) => setDraft((current) => current ? { ...current, [setting.key]: Number(event.target.value) } : current)}>
                            {setting.options?.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
                          </select>
                        ) : (
                          <input type="number" value={draft?.[setting.key] ?? ""} min={setting.min} max={setting.max} step={setting.step ?? 1} disabled={!draft || state === "saving"} onChange={(event) => setDraft((current) => current ? { ...current, [setting.key]: Number(event.target.value) } : current)} />
                        )}
                        {setting.unit && <span className="maintenance-unit">{setting.unit}</span>}
                      </td>
                      <td>{setting.min ?? "—"}–{setting.max ?? "—"}</td>
                      <td><span className={`maintenance-apply maintenance-apply-${setting.apply}`}>{setting.apply}</span></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>
        ))}
        <footer className="maintenance-actions">
          <span className={`maintenance-message maintenance-message-${state}`} role="status">{state === "loading" ? "Loading settings…" : message}</span>
          <button type="submit" className="maintenance-save-button" disabled={!draft || state === "loading" || state === "saving"}>{state === "saving" ? "Saving…" : "Save and apply"}</button>
        </footer>
      </form>
    </PaneFrame>
  );
}
